import fs from 'node:fs';

function loadEnv(file) {
  const out = {};
  if (!fs.existsSync(file)) return out;
  for (const line of fs.readFileSync(file, 'utf8').split(/\r?\n/)) {
    if (!line || line.startsWith('#') || !line.includes('=')) continue;
    const i = line.indexOf('=');
    out[line.slice(0, i).trim()] = line.slice(i + 1).trim().replace(/^["']|["']$/g, '');
  }
  return out;
}

const env = { ...loadEnv('.env.local'), ...loadEnv('.env'), ...process.env };
const KEY = env.SUPABASE_SERVICE_KEY || env.SUPABASE_SERVICE_ROLE_KEY;
const URL = env.NEXT_PUBLIC_SUPABASE_URL;
const COMMIT = process.argv.includes('--commit');
const H = { apikey: KEY, Authorization: `Bearer ${KEY}`, 'Content-Type': 'application/json' };

export const BODIES = {
  'lesson-aqeedah-التوحيد-تعريف-وأركان-0': {
    ar: 'التوحيد لغةً: مصدر «وحّد» أي جعل الشيء واحدًا. وشرعًا: إفراد الله سبحانه بما يختصّ به من الربوبية والألوهية والأسماء والصفات. وهو أوّل ما دعا إليه الأنبياء، وأوّل واجب على المكلّف، وأساس قبول الأعمال.\n\nوينقسم إلى ثلاثة أنواع: توحيد الربوبية، وهو إفراده بالخلق والرزق والتدبير؛ وتوحيد الألوهية، وهو إفراده بالعبادة، وهو مقصود الرسالة وأصل الخلاف مع المشركين؛ وتوحيد الأسماء والصفات، وهو إثبات ما أثبته الله لنفسه بلا تحريف ولا تعطيل ولا تكييف ولا تمثيل.\n\nوثمراته في الدنيا والآخرة: الأمن والاهتداء كما في قوله: «الذين آمنوا ولم يلبسوا إيمانهم بظلم أولئك لهم الأمن وهم مهتدون»، ومغفرة الذنوب، ودخول الجنة بغير حساب لمن كمل توحيده.',
    en: 'Tawhid linguistically means making something one. In religious terms it is singling out God with what belongs to Him alone: His Lordship, His exclusive right to worship, and His names and attributes. It is the first thing the prophets called to, the first duty of the accountable person, and the foundation for the acceptance of deeds.\n\nIt has three types: the oneness of Lordship, singling Him out in creation, provision, and governance; the oneness of worship, singling Him out in worship, which is the aim of the message and the root of the dispute with the polytheists; and the oneness of names and attributes, affirming what God affirmed for Himself without distortion, denial, asking how, or likening.\n\nIts fruits in this life and the next: security and guidance, as in "those who believe and do not mix their faith with wrong, theirs is security and they are guided," forgiveness of sins, and entry to Paradise without reckoning for one whose tawhid is complete.',
  },
  'lesson-aqeedah-أسماء-الله-الحسنى-وصفاته-1': {
    ar: 'الإيمان بأسماء الله وصفاته ركنٌ من أركان الإيمان بالله؛ فالله يُعرف بأسمائه الحسنى وصفاته العلى، وقد قال: «ولله الأسماء الحسنى فادعوه بها». وأسماؤه كلها حسنى، وصفاته كلها كمال لا نقص فيه.\n\nومن أبرز أسمائه: الله، والرحمن، والرحيم، والملك، والقدوس، والسلام، والعليم، والحكيم، والسميع، والبصير، والغفور، والودود. وكل اسمٍ يتضمّن صفة، والدعاء بها يكون بالتوسّل والتعريف والإخبار، لا بتحريف معانيها.\n\nوقد سلك أهل السنة في الصفات طريقًا وسطًا: إثباتٌ بلا تمثيل، وتنزيهٌ بلا تعطيل، امتثالًا لقوله: «ليس كمثله شيء وهو السميع البصير». وأخطاء الباب ثلاثة: التشبيه، والتعطيل، والتحريف؛ والصواب الجمع بين الإثبات والتنزيه مع تفويض الكيفية إلى الله.',
    en: 'Belief in God\u0027s names and attributes is part of faith in Him; God is known by His most beautiful names and sublime attributes, and He said: "To God belong the most beautiful names, so call upon Him by them." All His names are beautiful and all His attributes are perfection without deficiency.\n\nAmong His most prominent names are: Allah, the Most Merciful, the Especially Merciful, the Sovereign, the Most Holy, the Source of Peace, the All-Knowing, the Wise, the All-Hearing, the All-Seeing, the Forgiving, and the Loving. Each name includes an attribute, and calling upon Him by them is done through seeking, describing, and informing, not by distorting their meanings.\n\nAhl al-Sunnah took a middle path with the attributes: affirmation without likening, and transcendence without denial, in accord with "there is nothing like unto Him, and He is the Hearing, the Seeing." The errors in this chapter are three: likening, denial, and distortion; the correct approach combines affirmation and transcendence, entrusting the manner to God.',
  },
  'lesson-aqeedah-الإيمان-بالقدر-خيره-وشره-2': {
    ar: 'القدر تقدير الله سبحانه لكل ما كان وما سيكون، وإجراؤه للأمور على ما سبق في علمه. والإيمان به أصلٌ من أصول الإيمان، دلّ عليه قوله: «إنا كل شيء خلقناه بقدر»، وقوله: «وكان أمر الله قدرًا مقدورًا».\n\nومراتبه أربع: علم الله المحيط بكل شيء، وكتابته في اللوح المحفوظ، ومشيئته النافذة فلا يقع في ملكه ما لا يريد، وخلقه لكل شيء. ورتّب النبي ﷺ هذه المراتب في حديث جبريل حين سأله عن الإيمان.\n\nويُجمع بين القدر والمسؤولية: أنّ العبد له قدرةٌ واختيارٌ يَكتسب به فعله، فتُنسب إليه أفعاله التي كسبها، ولا يُحتجّ بالقدر على المعصية، بل يُحتجّ به عند المصائب؛ قال تعالى: «قل فللّه الحجة البالغة».\n\nوثمرة الإيمان به: الطمأنينة، وترك التسخّط، والعمل بالأسباب مع التوكل.',
    en: 'Divine decree is God\u0027s determination of everything that was and will be, and His executing of affairs according to what preceded in His knowledge. Belief in it is a pillar of faith, indicated by "We have created everything by measure" and "the command of God is a decree determined."\n\nIt has four levels: God\u0027s all-encompassing knowledge, His writing of it in the Preserved Tablet, His effective will so that nothing occurs in His dominion that He does not will, and His creation of all things. The Prophet ordered these levels in the hadith of Gabriel when he asked about faith.\n\nDecree and responsibility are reconciled in that the servant has ability and choice by which he earns his act, so his acquired deeds are attributed to him. Decree is not pleaded against sin but at times of calamity; He said: "Say: to God belongs the conclusive argument."\n\nThe fruit of believing in it is tranquillity, abandoning resentment, and acting upon the means while trusting.',
  },
  'lesson-aqeedah-الفرقة-الناجية-وأهل-السنة-والجماعة-3': {
    ar: 'أهل السنة والجماعة هم السالكون لما كان عليه النبي ﷺ وأصحابه، اعتقادًا وقولًا وعملًا؛ وهم الفرقة الناجية والطائفة المنصورة كما في حديث «وستفترق أمتي على ثلاث وسبعين ملة». وسُمّوا أهل السنة لتمسّكهم بسنة النبي ﷺ، وأهل الجماعة لاجتماعهم على الحقّ وعدم شذوذهم.\n\nوأصولهم في التلقّي: الكتاب والسنة على فهم السلف، وعدم تقديم العقل على النصّ، والتوسّط في باب الأسماء والصفات والقدر والوعيد، والجمع بين العلم والعمل، والاعتزاز بالانتساب إلى الأمة دون ادّعاء العصمة.\n\nويُلحظ أنّ الوصف مدحٌ للمنهج لا للأشخاص؛ فقد يُخلّ بعض المنتسبين به فيُردّ قوله إلى السنة لا يُهدم المنهج لأجله، ويُتأنّى في التبديع، ويُفرّق بين المقلّد الجاهل والداعية إلى البدعة.',
    en: 'Ahl al-Sunnah wa al-Jamaah are those who follow what the Prophet and his companions were upon in belief, word, and deed; they are the saved group and the aided faction, as in the hadith "my community will split into seventy-three sects." They are named the people of the Sunnah for holding to the Prophet\u0027s practice, and the people of the community for uniting upon truth without deviation.\n\nTheir principles of reception: the Quran and Sunnah as understood by the early generations, not prioritising reason over the text, moderation on names and attributes, decree, and warnings, combining knowledge and action, and taking pride in belonging to the community without claiming infallibility.\n\nThe description praises the method, not individuals; if some affiliates fall short, their statement is returned to the Sunnah, and the method is not demolished for their sake. Judgement of innovation is made with deliberation, distinguishing the ignorant imitator from the one who calls to innovation.',
  },
  'lesson-quran-تفسير-سورة-الفاتحة-4': {
    ar: 'سورة الفاتحة أمّ القرآن وأعظم سورةٍ فيه، وهي ركنٌ في الصلاة لا تصحّ بدونها كما في حديث «لا صلاة لمن لم يقرأ بفاتحة الكتاب». وقد جمعت أصول التوحيد والدعاء والهداية في سبع آيات.\n\nفافتُتحت بالحمد والثناء، ثم إفراد الله بالربوبية «رب العالمين» والرحمة «الرحمن الرحيم» والملك «مالك يوم الدين»، ثم إفراده بالعبادة «إياك نعبد وإياك نستعين»، ثم سؤال أعظم مطلوب وهو الهداية إلى الصراط المستقيم مع بيان طريق المنعَم عليهم وطريق المغضوب عليهم والضالين.\n\nومن أسرارها: أنّها جمعت بين الثناء والدعاء، وأنّ قراءتها في كل ركعة تجدّد الإيمان، وأنّ الله يقول في الحديث القدسي: «قسمتُ الصلاة بيني وبين عبدي نصفين»، وقد سمّاها النبي ﷺ «الصلاة» لعظيم منزلتها فيها.',
    en: 'Surat al-Fatihah is the mother of the Quran and its greatest surah; it is a pillar of prayer without which prayer is invalid, as in "there is no prayer for one who does not recite the Opening of the Book." It gathers the foundations of monotheism, supplication, and guidance in seven verses.\n\nIt opens with praise, then singles out God in Lordship, "Lord of all worlds," mercy, "the Most Merciful, the Especially Merciful," and sovereignty, "Master of the Day of Judgement," then singles Him out in worship, "You alone we worship and You alone we ask for help," then asks the greatest request, guidance to the straight path, showing the way of those favoured and the way of those who incurred wrath and went astray.\n\nIts secrets include: it joins praise with supplication, reciting it in every unit renews faith, and God says in the sacred hadith "I have divided the prayer between Myself and My servant into two halves." The Prophet named it "the prayer" for its great standing within it.',
  },
  'lesson-quran-أحكام-التجويد-الميسرة-5': {
    ar: 'التجويد لغةً: التحسين والإتيان بالشيء مُجَوَّدًا. واصطلاحًا: إخراج كل حرف من مخرجه مع إعطائه حقّه ومستحقّه من الصفات. وحكمه: واجبٌ عمليًّا في قراءة القرآن، وأما العلم به ففرض كفاية.\n\nوأهمّ أبوابه: مخارج الحروف وصفاتها، وأحكام النون الساكنة والتنوين (الإظهار، والإدغام، والإقلاب، والإخفاء)، وأحكام الميم الساكنة، والمدود (الطبيعي والفرعي)، واللامات (لام التعريف ولام الفعل)، والقلقلة، والتفخيم والترقيق.\n\nوغايته صون اللسان عن الخطأ في كتاب الله، والخطأ قسمان: جليّ وهو تغيير الحرف أو الحركة ويُحرّم، وخفيّ وهو خللٌ في الصفة لا يغيّر المعنى ويُكره. ويُتلقّى التجويد بالمشافهة عن شيخ مُتقن، فالصوت لا يُنقل بالكتابة وحدها.',
    en: 'Tajwid linguistically means beautifying and doing something well. Technically it is giving every letter its right and due from its articulation point and characteristics. Its ruling: practically obligatory in reciting the Quran, while knowing its science is a communal obligation.\n\nIts most important chapters: articulation points and letter characteristics; the rules of the silent nun and tanwin (clear, merging, conversion, and concealment); the rules of the silent mim; elongations, both natural and secondary; the rules of the definite article and the verbal lam; the echoing letters; and the rules of heaviness and lightness.\n\nIts purpose is to protect the tongue from error in God\u0027s Book. Error is of two kinds: clear, which changes a letter or vowel and is forbidden, and hidden, which is a flaw in the characteristic without changing meaning and is disliked. Tajwid is received orally from a skilled teacher, for sound cannot be conveyed by writing alone.',
  },
  'lesson-quran-أسباب-النزول-وأهميتها-6': {
    ar: 'أسباب النزول: الأحداث أو الأسئلة التي نزلت الآيات عقبها، وهي خبرٌ نقلي يُتلقّى بالرواية، ولا مجال للرأي فيه. ومن أشهر مصنفاته «أسباب النزول» للواحدي، و«لباب النقول» للسيوطي.\n\nوأهميتها عظيمة في التفسير: فهي تعيّن المراد في الآيات المحتملة، وتدفع الإشكال، وتبيّن من نزلت فيهم الآية، وتكشف حكمة التشريع والتدرّج فيه. ومن أمثلتها: نزول آية اللعان في قصة هلال بن أمية، وآية الظهار في خولة بنت ثعلبة.\n\nويُنبّه على أصلين: أوّلًا أنّ معرفة السبب لا تُخصّص اللفظ العامّ، فإنّ العبرة بعموم اللفظ لا بخصوص السبب؛ وثانيًا أنّ سبب النزول لا يُقبل إلا بسندٍ صحيح، وكثيرٌ ممّا يُنقل فيه ضعيفٌ فيُتوقّف فيه.',
    en: 'The reasons of revelation are the events or questions after which verses were revealed. They are transmitted reports received through narration, with no room for opinion. Among the best-known works on it are al-Wahidi\u0027s "Asbab al-Nuzul" and al-Suyuti\u0027s "Lubab al-Nuqul."\n\nTheir importance in exegesis is great: they determine the intended meaning in ambiguous verses, remove difficulty, show whom a verse concerned, and reveal the wisdom and gradual development of legislation. Examples include the verse of mutual imprecation concerning Hilal ibn Umayyah, and the verse of zihar concerning Khawlah bint Tha\u0027labah.\n\nTwo principles are noted: first, knowing the occasion does not restrict a general wording, since the criterion is the generality of the wording not the particularity of the occasion; and second, a reason is accepted only with a sound chain, and much of what is transmitted about it is weak, so one pauses over it.',
  },
  'lesson-quran-خطة-حفظ-القرآن-للمبتدئين-7': {
    ar: 'حفظ القرآن غايةٌ شريفة، وسبيله الجدّ والانتظام لا الكمّ المفرط؛ فقليلٌ دائم خيرٌ من كثيرٍ منقطع، كما في قوله ﷺ: «أحبّ الأعمال إلى الله أدومها وإن قلّ».\n\nوخطة المبتدئ على ثلاث مراحل: أوّلًا حفظ المفصّل وقصار السور حتى يتمكّن، ويُستحسن البدء بالجزء الثلاثين ثم التاسع والعشرين وهكذا تصاعدًا؛ وثانيًا تثبيت المحفوظ بمراجعة يومية منتظمة لا تُخِلّ بها العوارض؛ وثالثًا ربط الحفظ بالمعنى والتفسير ليَثبت ويتأثّر به القلب.\n\nويُعِين على ذلك: تحديد ورد يومي ثابت في وقتٍ معيّن من اليوم، وقراءة الورد على شيخٍ أو رفيق يُسمّع له، وتجنّب المعاصي فإنّها تُنسي القرآن، والدعاء والاستعانة بالله؛ فالقرآن أمانةٌ تحتاج صدقًا وصبرًا.',
    en: 'Memorising the Quran is a noble aim, achieved through seriousness and regularity rather than excessive quantity; a little that is constant is better than much that is cut off, as in the hadith "the deeds most loved by God are the most constant, even if few."\n\nThe beginner\u0027s plan has three stages: first, memorising the detailed surahs and short ones until established, and it is preferable to begin with the thirtieth part, then the twenty-ninth, and so on; second, consolidating what is memorised through regular daily review that passing circumstances do not disrupt; third, linking memorisation to meaning and exegesis so it becomes firmly rooted and the heart is affected.\n\nHelpful means: setting a fixed daily portion at a specific time, reciting the portion to a teacher or companion for correction, avoiding sins for they cause the Quran to be forgotten, and supplication and seeking God\u0027s help; the Quran is a trust requiring truthfulness and patience.',
  },
  'lesson-hadith-كتب-الحديث-الستة-8': {
    ar: 'الكتب الستة هي أوّل ما يُرجع إليه في السنة: صحيح البخاري، ثم صحيح مسلم، ثم سنن أبي داود، وسنن الترمذي، وسنن النسائي، وسنن ابن ماجة. والأصحّان أصحّ الكتب بعد القرآن بالاتفاق، واشترطا الصحة فيما يرويانه.\n\nومنهج كل كتاب يختلف: فالبخاري أشدّ شرطًا وأدقّ صناعة، ومسلم أمتن في سياق الألفاظ وجمع الطرق، وأبو داود ينتقي أحاديث الأحكام وبيّن ما سكت عنه، والترمذي يبين درجات الحديث ويعدّ الحسن، والنسائي شديد في الرجال، وابن ماجة أقلّها مرتبةً وفيه ما ضعُف.\n\nويُستفاد منها: أنّ العزو إلى الصحيحين لا يعني الصحة المطلقة، وأنّ ترتيب الكتب على الشهرة لا على القوة، وأنّ الحديث الضعيف الوارد فيها يُفحص سنده من مظانه الأخرى كالمسند والسنن الكبرى.',
    en: 'The six books are the first reference for the Sunnah: Sahih al-Bukhari, then Sahih Muslim, then the Sunan of Abu Dawud, al-Tirmidhi, al-Nasa\u0027i, and Ibn Majah. The two Sahihs are the most authentic books after the Quran by consensus, and their authors stipulated authenticity in what they narrated.\n\nThe method of each differs: al-Bukhari has the strictest condition and most precise craft; Muslim is firmer in wording and in gathering chains; Abu Dawud selects hadiths of rulings and clarified what he passed over; al-Tirmidhi explains grades and classifies the good; al-Nasa\u0027i is strict about narrators; and Ibn Majah is the lowest in rank with some weak material.\n\nThe lessons: attribution to the two Sahihs does not mean absolute authenticity; the books are ordered by fame, not strength; and a weak hadith in them should have its chain examined in other sources such as the Musnad and the major Sunan.',
  },
  'lesson-hadith-مصطلح-الحديث-تعريف-وأنواع-9': {
    ar: 'مصطلح الحديث: علمٌ يُبحث فيه عن أحوال الراوي والمروي من حيث القبول والردّ؛ فغايته تمييز المقبول من المردود من سنة النبي ﷺ. وأشهر مصنفاته: «المقدمة» لابن الصلاح، و«نخبة الفكر» لابن حجر وشرحه «نزهة النظر».\n\nوينقسم الحديث بحسب القبول إلى: صحيح (اتصل سنده بعدلٍ تامّ الضبط بلا شذوذٍ ولا علّة)، وحسن (خفّ ضبط راويه)، وضعيف (فقد شرطًا). وبحسب عدد الرواة إلى: متواتر (رواه جمعٌ يُستحال تواطؤهم على الكذب)، وآحاد. وبحسب الاتصال إلى: متصل، ومرسل، ومنقطع، ومعضل، ومدلَّس.\n\nومن أنواعه المردودة: الشاذ (مخالفة الثقة لمن هو أوثق منه)، والمنكر (مخالفة الضعيف)، والمعلَّل (علّة خفيّة تقدح في الصحة)، والموضوع (المكذوب المنسوب للنبي ﷺ)، وهو أشدّها حرمةً.',
    en: 'Hadith terminology is the science examining the states of the narrator and the narrated text in terms of acceptance and rejection; its aim is distinguishing the acceptable from the rejected in the Prophet\u0027s Sunnah. Its most famous works are Ibn al-Salah\u0027s "Muqaddimah" and Ibn Hajar\u0027s "Nukhbat al-Fikar" with his commentary "Nuzhat al-Nazar."\n\nBy acceptance, a hadith is sound, good, or weak. By number of narrators, it is mass-transmitted, which a group narrates whose collusion in lying is inconceivable, or solitary. By continuity, it is connected, loose, disconnected, broken, or concealed.\n\nAmong the rejected types: the anomalous, where a trustworthy narrator differs from a more reliable one; the rejected, where a weak narrator differs; the defective, having a hidden flaw that undermines authenticity; and the fabricated, falsely attributed to the Prophet, which is the gravest in prohibition.',
  },
  'lesson-fiqh-فقه-الطهارة-إزالة-النجاسة-12': {
    ar: 'الطهارة شرطٌ لصحة الصلاة والطواف ومسّ المصحف؛ والنجاسة عينٌ مستقذرة شرعًا يجب إزالتها عن البدن والثوب والمكان. والأصل في تطهيرها قوله تعالى: «وثيابك فطهر»، وقوله ﷺ في قصة الأعرابي: «أريقوا على بوله سجلًا من ماء».\n\nويُفرّق بين النجاسة المعنوية (الحدث) وتُزال بالوضوء أو الغسل أو التيمّم، والنجاسة الحسّية (الخبث) وتُزال بالماء الطهور حتى تزول عينها وأثرها من اللون والرائحة والطعم. وما شقّ زواله من الأثر بقي إلى المعفوّ عنه.\n\nومن الأحكام المتعلقة: أنّ الأصل في المياه الطهارة إلا ما تغيّر نجسًا، وأنّ النجاسة الجافّة تُزال بالفرك، وأنّ نجاسة الكلب تُغسل سبعًا إحداها بالتراب عند الجمهور، وأنّ ما لا يُدرك بالعين يُعفى عنه من أثرٍ يسيرٍ كرَشاشٍ أو غبارٍ.',
    en: 'Purity is a condition for the validity of prayer, circumambulation, and touching the Quran; impurity is a ritually filthy substance that must be removed from the body, clothing, and place. Its removal is grounded in "and your garments purify" and in the Prophet\u0027s instruction about a bedouin\u0027s urine: "pour a bucket of water over it."\n\nA distinction is made between ritual impurity, removed by ablution, bathing, or dry ablution, and physical impurity, removed with purifying water until its substance and traces of colour, smell, and taste vanish. What is difficult to remove of the trace remains forgiven.\n\nRelated rulings: water is pure in origin unless changed by impurity; dried impurity is removed by rubbing; contact with a dog\u0027s impurity is washed seven times, one with earth, per the majority; and what the eye cannot perceive is excused, such as slight splashes or dust.',
  },
  'lesson-fiqh-أحكام-الصلاة-شروط-وواجبات-وسنن-13': {
    ar: 'الصلاة الركن الثاني من أركان الإسلام، وأوّل ما يُحاسب عليه العبد يوم القيامة؛ فمن أقامها أقام دينه، ومن ضيّعها كان لما سواها أضيع. وهي صلةٌ بين العبد وربه، وأداؤها في وقتها من أعظم الواجبات.\n\nولها أقسام ثلاثة: شروطٌ لا تصحّ إلا بها، وهي الطهارة، وستر العورة، واستقبال القبلة، ودخول الوقت، والنية، والإسلام والعقل والتمييز؛ وواجباتٌ تبطل بتركها عمدًا، وهي تكبير الإحرام، وقراءة الفاتحة، والطمأنينة والاعتدال، والتشهّد الأخير، والتسليم؛ وأركانٌ وسننٌ تُقضى بالسجود عند النقص العارض.\n\nومن تمامها: الخشوع وحضور القلب، والطمأنينة فيها، وعدم الالتفات، والتسبيح فيها وذكر ما بعدها؛ وقد قال ﷺ: «جُعلت قرة عيني في الصلاة»، فكانت راحته عند النداء إلى الله.',
    en: 'Prayer is the second pillar of Islam and the first thing the servant is questioned about on the Day of Judgement; whoever establishes it establishes his religion, and whoever neglects it will neglect what comes after it more readily. It is a link between the servant and his Lord, and performing it on time is among the greatest obligations.\n\nIt has three categories: conditions without which it is invalid, namely purity, covering the body, facing the qibla, the entry of the time, intention, and being a rational, discerning Muslim; obligations whose deliberate omission invalidates it, namely the opening takbir, reciting the Opening of the Book, tranquillity and straightening, the final testimony, and the closing salutation; and pillars and recommended acts made up by prostration when omitted inadvertently.\n\nIts perfection includes: humility and presence of heart, tranquillity, avoiding turning away, and remembrance during and after it. The Prophet said, "my delight has been placed in prayer," finding his rest at the call to God.',
  },
  'lesson-fiqh-فقه-المعاملات-البيع-والشراء-14': {
    ar: 'المعاملات المالية مبنية على التراضي كما في قوله تعالى: «إلا أن تكون تجارةً عن تراضٍ منكم»، والأصل فيها الحلّ حتى يثبت الدليل على التحريم؛ ولذلك وردت النصوص بتحليل البيع وتحريم الربا والغرر والميسر.\n\nوشروط صحة البيع: التراضي بين العاقدين، وأن يكون المبيع معلومًا مملوكًا مقدورًا على تسليمه، وأن يكون منفعته مشروعة، وطهارة المبيع إذا كان ممّا يشترط فيه الطهارة، وتحديد الثمن تحديدًا يُرضي الطرفين.\n\nومن الممنوعات: بيع الغرر، وبيع المعدوم، وبيع العلّة (كبعض بيع الأعيان المنجّزة)، والاحتكار عند حاجة الناس، والبيع على بيع أخيه، والنجش، والرشوة في القضاء والحقوق، والربا قرضًا أو بيعًا، والمعاملات التي تغلب عليها المخاطرة كالمراهنات والفوائد القائمة على الميسر.',
    en: 'Financial dealings are built on mutual consent, as in "unless it be trade by mutual consent among you," and the default in them is permissibility until evidence of prohibition appears; hence the texts permit sale and forbid usury, uncertainty, and gambling.\n\nConditions for the validity of sale: mutual consent of the contracting parties; that the item be known, owned, and deliverable; that its benefit be legitimate; purity of what must be pure; and a price specified in a way that satisfies both parties.\n\nAmong the prohibited: sale with excessive uncertainty, sale of what does not exist, certain conditional sales with an option to annul, monopolising when people are in need, buying over another\u0027s purchase, bidding to raise prices, bribery in judgement and rights, usury whether in loan or sale, and dealings dominated by speculation such as betting and interest built on gambling.',
  },
  'lesson-fiqh-مبادئ-أصول-الفقه-15': {
    ar: 'أصول الفقه: العلم بالقواعد التي يُتوصّل بها إلى استنباط الأحكام الشرعية العملية من أدلّتها التفصيلية. وواضعه أبو حنيفة أوّلًا، ورتّبه الشافعي في «الرسالة»، ووسّعه الأصوليون بعده بالمصطلحات والمسائل.\n\nوموضوعه: الأدلة الشرعية من حيث ثبوتها ودلالتها، والقواعد اللغوية والأصولية التي تُستخرج بها الأحكام، وحال المجتهد والمقلّد. وأدلّته المتفق عليها: الكتاب، والسنة، والإجماع، والقياس، وأدلّة مختلفٌ فيها كالمصالح المرسلة والاستحسان والعرف والاستصحاب والذرائع.\n\nومن مباحثه المهمة: دلالات الألفاظ (العام والخاص، المطلق والمقيّد، الحقيقة والمجاز، الأمر والنهي)، ومقاصد الشريعة، ومقاصد التكليف، والاجتهاد والتقليد والترجيح بين الأقوال. ودَرْسُه لازمٌ لفهم الاختلاف الفقهي وتقدير الأقوال.',
    en: 'Usul al-fiqh is the science of the principles by which practical legal rulings are derived from their detailed evidence. Abu Hanifah first set it in motion, al-Shafi\u0027i organised it in "al-Risalah," and later scholars expanded it with terminology and issues.\n\nIts subject is the revealed evidence in terms of authenticity and indication, the linguistic and juristic principles by which rulings are derived, and the state of the one who exercises judgement and the one who follows. Its agreed sources are the Quran, the Sunnah, consensus, and analogy, with disputed ones such as unattached interests, juristic preference, custom, presumption of continuity, and blocking the means.\n\nImportant topics include: implications of wording such as the general and the specific, the absolute and the restricted, literal and figurative, command and prohibition; the objectives of the Shariah; the purposes of obligation; and judgement, following, and preferring between opinions. Studying it is necessary to understand juristic disagreement and weigh opinions.',
  },
  'fatwa-fiqh-هل-يجوز-الجمع-بين-الصلاتين-في-السفر؟-16': {
    ar: 'الجمع بين الصلاتين في السفر رخصةٌ ثابتة بالسنة؛ جمع النبي ﷺ في غزوة تبوك بين الظهر والعصر، وبين المغرب والعشاء، وأثبته ابن عمر في مسيره. والجمع نوعان: جمع تقديم (تُصلّى الثانية مع الأولى في وقت الأولى)، وجمع تأخير (تُصلّى الأولى مع الثانية في وقت الثانية).\n\nوشروط الجمع: أن يكون السفر مباحًا طويلًا عرفًا، وأن يكون الجمع بين الظهر والعصر أو المغرب والعشاء، وألّا يُنوى به مجرّد التوسّع في الحضر؛ وأمّا القصر فيجوز في السفر المباح مطلقًا ولو مع عدم الجمع.\n\nوالأفضل: أن يختار الأرفق بحاله؛ فإن كان السفر ممتدًّا بلا توقّف جمع تأخيرًا في وقت الثانية، وإن كان يشقّ عليه الانتظار جمع تقديمًا، مع الحرص على أداء الصلاة في جماعة إذا تيسّر ذلك، والمراد تيسير العبادة لا إسقاطها.',
    en: 'Combining two prayers during travel is a concession established in the Sunnah; the Prophet combined the noon and afternoon prayers, and the sunset and evening prayers, and Ibn Umar affirmed it on his journey. It is of two kinds: advance combining, where the second is prayed with the first at the first time, and delayed combining, where the first is prayed with the second at the second time.\n\nIts conditions: that the journey be permissible and long by custom; that the combining be between noon and afternoon, or sunset and evening; and that it not be intended merely to widen one\u0027s options while resident. Shortening, by contrast, is permitted on a permissible journey even without combining.\n\nThe better course is to choose what suits one\u0027s condition: on continuous travel without stopping, delayed combining at the second time; where waiting is difficult, advance combining, with care to pray in congregation when possible. The aim is easing worship, not nullifying it.',
  },
  'fatwa-fiqh-حكم-المعاملات-بالربا-18': {
    ar: 'الربا محرّم قطعًا بالكتاب والسنة والإجماع؛ قال تعالى: «وأحلّ الله البيع وحرّم الربا»، وقال: «يا أيها الذين آمنوا اتقوا الله وذروا ما بقي من الربا إن كنتم مؤمنين»، وقد لعن النبي ﷺ آكل الربا وموكله وكاتبه وشاهديه وقال: «هم سواء».\n\nوالربا نوعان: ربا الفضل، وهو زيادةٌ في بيع الأموال الربوية مع اتفاق الجنس والعلّة؛ وربا النسيئة، وهو تأخير أو زيادةٌ مقابل الأجل. ويدخل في الربا: فوائد القروض، والزيادة في المبادلة النقدية، والبيع المشروط بزيادة عند حلول الأجل، وبعض صور القرض الذي جرّ نفعًا.\n\nومن مفاسده: أكل أموال الناس بالباطل، وتسلّط الغنيّ على الفقير، وإفساد العدل الاقتصادي، ومحق البركة؛ كما في قوله: «يمحق الله الربا ويربي الصدقات». والتوبة منه تكون بتركه وردّ الزيادة لصاحبها إن أمكن، والاقتصار على عقود مشروعة كالبيع والشركة والمضاربة والإجارة.',
    en: 'Usury is definitively forbidden by the Book, the Sunnah, and consensus; He said: "God has permitted trade and forbidden usury," and "O you who believe, fear God and give up what remains of usury, if you are believers." The Prophet cursed the one who takes usury, the one who pays it, its scribe, and its two witnesses, saying "they are the same."\n\nIt has two kinds: excess usury, an increase in exchanging usurious goods of the same kind and cause, and deferral usury, a delay or increase in return for the term. Included in it are: interest on loans, an increase in exchanging cash, a sale conditional on an increase at maturity, and some forms of loans that yield a benefit.\n\nAmong its harms: consuming people\u0027s wealth unjustly, the rich dominating the poor, corrupting economic justice, and erasing blessing, as in "God destroys usury and increases charity." Repentance is by abandoning it, returning the increase to its owner if possible, and limiting oneself to legitimate contracts such as sale, partnership, silent partnership, and hire.',
  },
  'story-seerah-مولد-النبي-وبدء-الوحي-19': {
    ar: 'وُلد النبي ﷺ في مكة عام الفيل، يتيمًا؛ توفي أبوه عبد الله قبل ولادته، وتوفيت أمه آمنة وله ست سنين، فكفله جدّه عبد المطّلب ثم عمّه أبو طالب. ونشأ على الفطرة والعفّة، واشتغل بالرعي ثم التجارة، وعُرف بين قريش بالصادق الأمين.\n\nولمّا استكمل أربعين سنة على المشهور، بُعث بالوحي في غار حراء؛ فجاءه جبريل وقال: «اقرأ»، فنزلت أوائل سورة العلق. فرجع يرجف فؤاده إلى خديجة رضي الله عنها، فثبّتها وقالت كلمتها المشهورة: «والله لا يخزيك الله أبدًا؛ إنك لتصل الرحم، وتحمل الكَلّ، وتكسب المعدوم، وتعين على نوائب الحق».\n\nثم فتر الوحي مدّة ثم عاد بسورة المدثر: «يا أيها المدثر، قم فأنذر». وفي هذا دروس: أنّ الفرح بعد الشدّة، وأنّ الإعداد الإلهي سبق الرسالة، وأنّ أعظم ما يُستعان به على حِمل الرسالة خُلقُ الصدق والأمانة.',
    en: 'The Prophet was born in Makkah in the Year of the Elephant, an orphan; his father Abdullah died before his birth, and his mother Aminah died when he was six, so his grandfather Abd al-Muttalib then his uncle Abu Talib cared for him. He grew on natural purity and chastity, worked first as a shepherd then in trade, and was known among Quraysh as the truthful and trustworthy.\n\nWhen he reached forty, according to the well-known report, he was sent with revelation in the cave of Hira; Gabriel came to him and said "recite," and the opening of Surat al-Alaq was revealed. He returned trembling to Khadijah, who steadied him with her famous words: "By God, God will never disgrace you; you maintain ties of kinship, carry the burdened, earn for the destitute, and aid in the calamities of truth."\n\nThen revelation paused, and returned with Surat al-Muddaththir: "O you covered one, arise and warn." The lessons: relief follows hardship, divine preparation precedes the message, and the greatest support for carrying the message is the character of truthfulness and trust.',
  },
  'story-seerah-عهد-أبو-بكر-الصديق-رضي-الله-عنه-20': {
    ar: 'أبو بكر الصديق أول الخلفاء الراشدين وأول من آمن من الرجال، وصاحب النبي ﷺ في الهجرة ورفيقه في الغار؛ قال تعالى: «إذ يقول لصاحبه لا تحزن إنّ الله معنا». وبُويع بالخلافة بعد وفاة النبي ﷺ في سقيفة بني ساعدة بإجماع الصحابة.\n\nومن أعظم مواقفه: تثبيت الأمة عند وفاة النبي ﷺ بقوله: «من كان يعبد محمدًا فإنّ محمدًا قد مات، ومن كان يعبد الله فإنّ الله حيّ لا يموت»، ثم مواجهة الردة ومنع الزكاة بحزمٍ مع بذل النصح قبل القتال، وإنفاذ جيش أسامة كما أمر النبي ﷺ، ودفع الفتوح إلى الشام والعراق، وجمع القرآن في مصحفٍ واحد بمشورة عمر رضي الله عنه.\n\nوأدار الأمة بالشورى والعدل والزهد؛ فكان راتبه أقلّ من راتب غيره، وردّ ما أخذ عند مرض الموت، وأوصى بتقوى الله والثبات على ما كان عليه النبي ﷺ وأصحابه. ومات بعد سنتين وثلاثة أشهر من خلافته، وقد تركت خلافته القصيرة أثرًا في بناء الدولة ورسم منهج الحكم الراشد.',
    en: 'Abu Bakr al-Siddiq was the first of the rightly guided caliphs, the first man to believe, and the Prophet\u0027s companion in migration and in the cave; He said: "when he said to his companion, do not grieve, God is with us." He was given allegiance after the Prophet\u0027s death in the courtyard of Banu Sa\u0027idah by consensus of the companions.\n\nAmong his greatest stands: steadying the community at the Prophet\u0027s death with his words, "whoever worshipped Muhammad, Muhammad has died; whoever worshipped God, God is living and does not die"; confronting apostasy and the withholding of zakat with firmness while offering advice before fighting; dispatching Usamah\u0027s army as the Prophet had ordered; launching conquests into Syria and Iraq; and gathering the Quran into a single codex on Umar\u0027s counsel.\n\nHe governed through consultation, justice, and asceticism; his stipend was less than others\u0027, he returned what he had taken when he fell ill, and he enjoined God-consciousness and adherence to what the Prophet and his companions were upon. He died after two years and three months in office, leaving a short caliphate that shaped the state and defined the method of rightly guided rule.',
  },
  'lesson-tazkiyah-حسن-الخلق-في-الإسلام-21': {
    ar: 'حسن الخلق من أعظم مقاصد البعثة؛ قال ﷺ: «إنما بُعثت لأتمّم صالح الأخلاق»، وقال: «أكمل المؤمنين إيمانًا أحسنهم خلقًا». وهو كلمةٌ جامعة تشمل الرفق، والبشر، وطلاقة الوجه، وكفّ الأذى، والعفو، والصدق، والحياء.\n\nوقد بيّن النبي ﷺ عظم جزائه: «ما شيءٌ أثقل في ميزان المؤمن من خُلقٍ حسن»، وأخبر أنّ صاحب الخُلق الحسن يبلغ درجة الصائم القائم، وقال: «أنا زعيمٌ ببيتٍ في أعلى الجنة لمن حسن خُلقه». وهو من أكثر ما يُدخل الجنة؛ ففي الحديث: «أكثر ما يُدخل الناس الجنة تقوى الله وحسن الخُلق».\n\nويُكتسب حسن الخلق بالمجاهدة والمخالطة والاقتداء؛ فمن رامه فليصاحب أهل الأدب، وليتدبّر سيرة النبي ﷺ، وليجاهد نفسه على ردّ الغلظة إلى الحلم، وليَعُدّ أثر كلمته قبل أن يتكلّم.',
    en: 'Good character is among the greatest aims of the mission; the Prophet said: "I was only sent to complete noble character," and "the most complete of the believers in faith are the best of them in character." It is a comprehensive term covering gentleness, cheerfulness, a welcoming face, refraining from harm, forgiveness, truthfulness, and modesty.\n\nThe Prophet showed its great reward: "nothing is heavier in a believer\u0027s scale than good character," he informed that one of good character attains the rank of the fasting and praying, and he said: "I guarantee a house in the highest part of Paradise for one whose character is good." It is among what most admits people to Paradise: "most of what admits people to Paradise is God-consciousness and good character."\n\nGood character is acquired through striving, mixing with people, and imitation: let one who seeks it keep company with people of refinement, ponder the Prophet\u0027s life, strive against harshness toward forbearance, and weigh the effect of his words before speaking.',
  },
  'lesson-tazkiyah-أذكار-الصباح-والمساء-22': {
    ar: 'أذكار الصباح تقال بعد صلاة الفجر إلى طلوع الشمس، وأذكار المساء بعد صلاة العصر إلى المغرب على قول جمهور أهل العلم؛ والمقصود تحصين المؤمن وإقامة صلته بالله في طرفي النهار. وقد وردت بأسانيد صحيحة في كتب الحديث، وأشهرها ما في «عمل اليوم والليلة» و«الأذكار» للنووي.\n\nومن أبرزها: آية الكرسي، وسورتا الفلق والناس والإخلاص ثلاثًا، و«أعوذ بكلمات الله التامات من شرّ ما خلق» ثلاثًا، و«بسم الله الذي لا يضرّ مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم» ثلاثًا، و«اللهم بك أصبحنا وبك أمسينا...» ، و«حسبي الله لا إله إلا هو» سبعًا، و«اللهم إني أسألك العفو والعافية» ثلاثًا.\n\nويُشترط فيها: حضور القلب وتدبّر المعنى، والإتيان بالأعداد الواردة، وعدم الاستعجال، والدوام عليها؛ فمن أدامها حُفظ بإذن الله، ومن أضاعها فاته خيرٌ عظيم. والذكر عبادةٌ يُثاب عليها الفاعل، وأجره يجري ما دام العبد مواظبًا عليه.',
    en: 'Morning remembrance is said after the dawn prayer until sunrise, and evening remembrance after the afternoon prayer until sunset according to the majority. The purpose is fortifying the believer and establishing his connection with God at the two ends of the day. They are reported with sound chains in the hadith books, most famously in the works on the day and night and al-Nawawi\u0027s "al-Adhkar."\n\nAmong the most prominent: the verse of the throne; the three suras of refuge and sincerity three times; "I seek refuge in God\u0027s perfect words from the evil of what He created" three times; "in the name of God, with whose name nothing on earth or in heaven harms, and He is the Hearing, the Knowing" three times; "O God, by You we enter the morning and by You the evening"; "God is sufficient for me, there is no deity but Him" seven times; and "O God, I ask You forgiveness and wellbeing" three times.\n\nIts conditions: presence of heart and reflection on meaning, the transmitted numbers, without haste, and persistence; whoever persists is protected by God\u0027s leave, and whoever neglects it misses great good. Remembrance is worship for which the doer is rewarded, and its reward continues as long as the servant keeps it up.',
  },
  'lesson-dawah-منهج-الأنبياء-في-الدعوة-23': {
    ar: 'منهج الأنبياء في الدعوة يقوم على أصلين: وحدة الغاية وهي إفراد الله بالعبادة، وتنوّع الوسيلة بحسب حال المدعوّين. وقد قال تعالى لنوح: «أن اعبدوا الله واتقوه وأطيعون»، ودعا كل نبي قومه إلى التوحيد أوّلًا ثم إلى طاعة الرسول.\n\nووسائلهم: الحكمة وهي العلم والرفق، والموعظة الحسنة وهي التذكير بالرحمة والتخويف من العقاب، والجدال بالتي هي أحسن مع أهل الجدل؛ مع الصبر على الأذى، وعدم اليأس من الاستجابة، والتربّع في الدعوة إلى التغيير، وترك الحساب على الله: «إن عليك إلا البلاغ».\n\nودروس الدعوة من قصصهم: أنّ النتائج بيد الله لا بيد الداعية، وأنّ القليل المُثمِر خيرٌ من الكثير غير المؤثّر، وأنّ بناء الرجال يسبق بناء المؤسسات، وأنّ القدوة العملية أبلغ من الكلام؛ فمن صلحت سريرته صلح علانيته، وكان لدعوته أثر.',
    en: 'The prophets\u0027 method in dawah rests on two roots: unity of aim, which is singling out God in worship, and diversity of means according to the state of those addressed. He said to Noah: "worship God, fear Him, and obey me," and every prophet called his people to monotheism first, then to obey the messenger.\n\nTheir means: wisdom, which is knowledge and gentleness; good exhortation, which reminds of mercy and warns of punishment; and arguing in the best manner with those who argue; along with patience under harm, not despairing of response, gradualism in calling to change, and leaving the reckoning to God: "yours is only the conveyance."\n\nLessons from their stories: results are in God\u0027s hand, not the caller\u0027s; a little that bears fruit is better than much that has no effect; building people precedes building institutions; and practical example is more eloquent than words; whoever\u0027s inner state is sound, his outward is sound and his call has effect.',
  },
  'lesson-dawah-كيفية-إعداد-خطبة-الجمعة-24': {
    ar: 'خطبة الجمعة عبادةٌ لها شروطٌ وآداب؛ فتُلقى قبل الصلاة على المنبر، ويُشترط أن تكون بعد الزوال، وأن يجلس الإمام بين الخطبتين، وأن يسمعها الحاضرون. وأركانها: الحمد، والصلاة على النبي ﷺ، والوصية بالتقوى، وقراءة آية، والدعاء للمؤمنين في الثانية عند كثير من الفقهاء.\n\nوأصول الإعداد: اختيار موضوعٍ واحدٍ واضحٍ يتصل بحال الناس، وتحديد الهدف منه، وجمع مادّته من القرآن والسنة وأقوال العلماء، وترتيب عناصره (مقدّمة · تقسيم · أدلّة · ثمرات · خاتمة)، ثم تحرير العبارة لتكون قصيرةً سهلة.\n\nوآداب الإلقاء: الاقتصاد في الطول فلا يملّ السامع، وحسن الصوت والوقفات، والنظر في الحاضرين، ولا سيّما البُعد عن التعريض بالأشخاص والانفعال غير المحسوب. والخطبة النافعة ما انتقل أثرها من المنبر إلى العمل؛ فالحسّ الوعظي ثمرته العمل لا الإعجاب بالكلام.',
    en: 'The Friday sermon is a worship with conditions and etiquettes; it is delivered before the prayer from the pulpit, and it is required that it be after the sun\u0027s decline, that the imam sit between the two sermons, and that those present hear it. Its pillars: praise, blessing on the Prophet, enjoining God-consciousness, reciting a verse, and supplicating for the believers in the second according to many jurists.\n\nPrinciples of preparation: choosing one clear topic connected to people\u0027s condition, defining its aim, gathering material from the Quran, Sunnah, and scholars\u0027 statements, ordering its elements (introduction, division, evidence, fruits, conclusion), then refining the wording to be short and easy.\n\nEtiquettes of delivery: moderation in length so the listener does not tire, good voice and pauses, looking at those present, and above all avoiding insinuation about individuals and uncalculated passion. A beneficial sermon is one whose effect moves from the pulpit to action; the fruit of preaching is practice, not admiration of words.',
  },
  'faq-responses-الرد-على-شبهة-لماذا-يسمح-الله-بالمعاناة؟-25': {
    ar: 'المعاناة في الدنيا ابتلاءٌ واختبار، والدنيا دار امتحان لا دار جزاء؛ قال تعالى: «الذي خلق الموت والحياة ليبلوكم أيّكم أحسن عملًا»، وقال: «ولنبلونّكم بشيء من الخوف والجوع... وبشّر الصابرين». فوجود الألم لا ينافي الرحمة، بل هو جزءٌ من نظام التكليف.\n\nوحِكَمُ الابتلاء متعدّدة: تمحيص المؤمن ورفع الدرجات، وتكفير السيئات، وردّ العبد إلى ربّه، وتمييز الصادق من المدّعي، وإظهار معادن النفوس، وإقامة السنن في تمحيص الأمة. وقد قال ﷺ: «أشدّ الناس بلاءً الأنبياء ثم الصالحون».\n\nومن كمال العدل: أنّ الجزاء الأخروي يُعوّض كلّ ألم، فلا يبقى مظلومٌ بلا قصاص، ولا مبتلى بلا أجر. والقصص تبيّن أنّ الفرج يأتي بعد الشدّة كقصة يونس ويعقوب ومريم؛ ولذلك كان المؤمن بين أجرٍ إن صبر ورفعةٍ إن احتسب، فلا يعترض على القدر بل يعمل بالأسباب ويسأل الله العافية.',
    en: 'Suffering in this world is trial and testing, and the world is a place of examination, not recompense; He said: "who created death and life to test you as to which of you is best in deed," and "We will surely test you with something of fear and hunger... and give good tidings to the patient." The existence of pain does not contradict mercy; it is part of the system of accountability.\n\nThe wisdoms of trial are many: refining the believer and raising his ranks, expiating sins, returning the servant to his Lord, distinguishing the truthful from the claimant, revealing the true nature of souls, and establishing the laws by which a community is sifted. The Prophet said: "the most severely tested people are the prophets, then the righteous."\n\nPart of perfect justice is that the reward of the Hereafter compensates every pain, so no wronged person remains without retribution and no sufferer without reward. The stories show relief comes after hardship, as with Jonah, Jacob, and Mary; the believer thus stands between reward if patient and elevation if seeking recompense, not objecting to decree but acting on the means and asking God for wellbeing.',
  },
  'faq-responses-الرد-على-العلمانية-فصل-الدين-عن-الحياة-26': {
    ar: 'دعوى العلمانية أنّ الدين شأنٌ فرديّ يُفصل عن الدولة والمجتمع، وأنّ التشريع يُستمدّ من العقل والتجربة. والردّ عليها من ثلاثة وجوه:\n\nأوّلًا: أنّ الإسلام منهجٌ شامل؛ فالنصوص تناولت العبادات والمعاملات والأخلاق والسياسة والقضاء، وقال تعالى: «وأن احكم بينهم بما أنزل الله». وثانيًا: أنّ الفصل التامّ لا يتحقّق عمليًّا؛ فالدول التي رفعته شرّعت قيمًا بديلةً وأحكامًا ملزمة، فلم تستغنِ عن تشريع، وإنما أبدلت مصدره. وثالثًا: أنّ الحياد المزعوم في المسائل الأخلاقية يفتح الباب للفوضى والتشريع بالأهواء وتغليب القويّ.\n\nوالصواب: التمييز بين ما هو من اختصاص الوحي (العقيدة والأخلاق والتشريع والقيم) وما هو من اختصاص العقل والتجربة في العلوم الدنيوية، مع الأخذ بالعلوم النافعة من أي أمّة، وعدم إلغاء الدين في المجال العام؛ فإنّ أثر التدين في المجتمع أثرٌ في الأمن والعدل والتراحم.',
    en: 'The secular claim is that religion is a private matter separated from state and society, and that legislation is drawn from reason and experience. It is answered on three fronts:\n\nFirst, Islam is a comprehensive way; the texts address worship, dealings, ethics, politics, and judiciary, and He said: "judge between them by what God has revealed." Second, total separation is not realised in practice; states that raised its banner legislated alternative values and binding rules, so they never dispensed with legislation, only replaced its source. Third, the claimed neutrality in moral questions opens the door to disorder, legislating by whim, and favouring the strong.\n\nThe correct approach is distinguishing what belongs to revelation (creed, ethics, legislation, and values) from what belongs to reason and experience in worldly sciences, taking useful knowledge from any nation, and not removing religion from public life; for religiosity affects security, justice, and mutual mercy in society.',
  },
  'faq-responses-الرد-على-شبهة-تحريف-القرآن-27': {
    ar: 'القرآن الكريم محفوظٌ بحفظ الله؛ قال تعالى: «إنا نحن نزلنا الذكر وإنا له لحافظون». وقد تكفّل الله بحفظه لفظًا ومعنى، ولم يقع فيه تحريفٌ كما وقع في كتب من قبله؛ فقال عن أهل الكتاب: «يحرّفون الكلم عن مواضعه».\n\nووجوه حفظه: جمعه في عهد أبي بكر، ونسخه في مصحفٍ واحد في عهد عثمان رضي الله عنه بالاعتماد على الرقاع والمحفوظ وإجماع الحفاظ، وتواتر نقله جيلًا عن جيلٍ بالسماع والكتابة، ووحدة المصحف في الأمة كلها حتى اليوم بدقّة لا نظير لها في كتابٍ آخر.\n\nودعوى التحريف تُدفع بوجوه: أنّ القرآن لا يُنقل إلا بالتواتر، وأنّ الحفاظ بالعدد الهائل في كل عصرٍ يمنعون التحريف، وأنّ اختلاف القراءات ليس تحريفًا بل تنويعٌ في اللفظ الثابت وثباته في المعنى، وأنّ الشبهات في هذا الباب إنما تُبنى على أوهام في النقل لا على أدلة صحيحة.',
    en: 'The Quran is preserved by God\u0027s protection; He said: "It is We who revealed the reminder, and it is We who will preserve it." God guaranteed its preservation in wording and meaning, and no distortion occurred in it as occurred in the books before it; of the People of the Book He said: "they distort words from their places."\n\nAspects of its preservation: its collection in Abu Bakr\u0027s time; its copying into a single codex in Uthman\u0027s time relying on parchments, memorisation, and the consensus of the memorisers; its mass transmission generation after generation by hearing and writing; and the unity of the codex across the whole community to this day with an accuracy unmatched by any other book.\n\nThe claim of distortion is refuted on several grounds: the Quran is transmitted only by mass transmission; the enormous number of memorisers in every age prevents distortion; differences in recitation are not distortion but variation in a fixed wording with stable meaning; and the doubts raised here rest on misconceptions in transmission, not sound evidence.',
  },
  'faq-responses-الرد-على-شبهة-ظلم-المرأة-في-الإسلام-28': {
    ar: 'الإسلام كرّم المرأة تكريمًا أصيلًا؛ فقد جعل لها الذمة المالية المستقلة، والحرية في التملّك والعقد، وحقّ التعليم والعمل، وحقّ الميراث الذي كانت محرومة منه في الجاهلية، وأوصى بها في الوالدين: «وبالوالدين إحسانًا».\n\nوأمّا ما يُتوهّم من ظلمٍ في الميراث أو الشهادة أو العمل، فمردّه إلى الغفلة عن القاعدة: «ولهنّ مثل الذي عليهنّ بالمعروف»، وعن التوزيع بحسب الأعباء لا بحسب الجنس؛ فالرجل مطالبٌ بالنفقة والديّة والمهر، والمرأة تُعفى من النفقة على أحد، وتُقدّم لها أحكام المخاطبة والقيام على الأولاد. وأمّا الشهادة فنظامٌ لحفظ الحقوق بحسب الأمانة والاطّلاع، وهو في مواضع كثيرة متساوٍ.\n\nوالنصوص الدالة على الفضل في العبادة والأجر عامّةٌ للجنسين: «من عمل صالحًا من ذكرٍ أو أنثى وهو مؤمن فلنحيينّه حياةً طيبة». ومن هنا كان المنصفون من غير المسلمين يشهدون بإنصاف الإسلام للمرأة مقارنةً بعصورٍ سابقة أُهدرت فيها حقوقها إهدارًا صريحًا.',
    en: 'Islam honoured women with a deep, original honour: it granted them independent financial standing, freedom to own and contract, the right to education and work, and the right of inheritance from which they were deprived in the pre-Islamic era, and it enjoined kindness to parents: "and to parents, good treatment."\n\nAs for the imagined wrongs regarding inheritance, testimony, or work, they stem from ignoring the rule "they have rights similar to those over them, in kindness," and from the distribution being according to burdens, not gender; the man is charged with maintenance, blood money, and dowry, while the woman is exempt from maintaining anyone and is granted rulings of being addressed and caring for children. As for testimony, it is a system for preserving rights according to trustworthiness and knowledge, and in many cases it is equal.\n\nThe texts indicating virtue in worship and reward are general to both sexes: "whoever does righteousness, whether male or female, while believing, We will surely give them a good life." Thus fair-minded non-Muslims have testified that Islam was just to women compared with earlier ages in which their rights were plainly squandered.',
  },
  'faq-doubts-3': {
    ar: 'دعوى أنّ الإسلام يظلم المرأة دعوى تحتاج بيّنة، والحقّ أنّ الإسلام أعطى المرأة ما لم تكن تحلم به في الجاهلية: الذمة المالية المستقلة، وحقّ التملّك والتصرّف في مالها بلا إذن وليّها، والميراث الذي كانت تُمنعه، والعناية بالتعليم وحفظ العرض وإنصافها عند الطلاق بالأحكام التي لا تُبطل حقّها.\n\nوالنظام الشرعي يوزّع الحقوق بحسب الأعباء لا بحسب الجنس؛ فالرجل عليه النفقة والمهر والديّة والعمل والتكليف، والمرأة عليها ما في وسعها، وتُعفى من الإنفاق على أحد. هذا توزيعٌ يوافق الحكمة والتكامل لا الظلم، ولو نُظرت آثار الفقه الإسلامي في حياة المرأة لرُئي أنّه أعظم من أنظمةً أخرى بلغت حدّ المخاطرة بحياة المرأة في العمل والحرب والقانون.\n\nويُضاف: أنّ النصوص جعلت الجزاء في العبادة والأجر عامًّا للجنسين، وأنّ التكريم في النسب والصحبة والأمومة خاصٌّ بالمرأة؛ فقد قال ﷺ حين سُئل من أحقّ الناس بحسن الصحبة؟ قال: «أمك» ثلاثًا، «ثم أبوك».',
    en: 'The claim that Islam wrongs women requires proof, whereas the truth is that Islam gave women what she could not imagine in the pre-Islamic era: independent financial standing, the right to own and dispose of her wealth without her guardian\u0027s permission, the inheritance she was denied, care for education and protection of honour, and fair treatment in divorce through rulings that do not nullify her right.\n\nThe revealed system distributes rights according to burdens, not gender; the man bears maintenance, dowry, blood money, work, and accountability, while the woman bears what is within her capacity and is exempt from maintaining anyone. This is a distribution consistent with wisdom and complementarity, not injustice. Were the effects of Islamic jurisprudence on women\u0027s lives considered, it would be seen as greater than other systems that have gone as far as risking women\u0027s lives in work, war, and law.\n\nIt is added: the texts make reward in worship general to both sexes, and honour in lineage, companionship, and motherhood specific to women; when the Prophet was asked who is most deserving of good companionship, he said: "your mother," three times, "then your father."',
  },
  'fiqh-intro': {
    ar: 'الفقه الإسلامي هو معرفة الأحكام الشرعية العملية المستمدّة من أدلّتها التفصيلية، وهو ثمرة الوحي وعلمٌ يُنظّم حياة المسلم في عبادته ومعاملاته وأحواله الأسرية وأخلاقه العامة. وأبوابه الكبرى أربعة: العبادات، والمعاملات المالية، والأحوال الشخصية، والأحكام الجنائية والعقوبات.\n\nومذاهب الفقه المشهورة أربعة: الحنفي، والمالكي، والشافعي، والحنبلي؛ وكلّها مناهج استنباط من الكتاب والسنة على قواعد أصولية، واختلافها في الفروع اختلاف تنوّعٍ لا تضادّ. ومن الإنصاف ألّا يُنسب إلى مذهبٍ ما لم يقله أهله، ولا يُقدّم التعصّب على طلب الحقّ.\n\nويُتعلّم الفقه بالتلقّي والتدرّج: يبدأ الطالب بمختصرٍ في العبادات مع دليله، ثم يتوسّع في المعاملات والأحوال؛ ومعرفة أحكام الصلاة والطهارة أوّل الواجبات العملية، كما في قوله ﷺ: «الصلاة على وقتها» عند سؤاله عن أحبّ عملٍ إلى الله.',
    en: 'Islamic jurisprudence is knowing the practical legal rulings derived from their detailed evidence; it is the fruit of revelation and a science organising a Muslim\u0027s life in worship, dealings, family matters, and public ethics. Its major chapters are four: worship, financial dealings, personal status, and criminal rulings and penalties.\n\nThe well-known schools of jurisprudence are four: Hanafi, Maliki, Shafi\u0027i, and Hanbali; all are methods of deriving rulings from the Quran and Sunnah on juristic principles, and their differences in branches are differences of variety, not contradiction. Fairness requires not attributing to a school what its adherents do not say, and not preferring partisanship over seeking truth.\n\nJurisprudence is learned by receiving and gradual study: the student begins with a concise text on worship with its evidence, then expands into dealings and personal status. Knowing the rulings of purity and prayer is the first practical duty, as when the Prophet was asked about the deed most loved by God and said: "prayer at its time."',
  },
  'lesson-learnsteps-1': {
    ar: 'أوّل ما يبدأ به طالب العلم: تصحيح العقيدة؛ فيتعلّم أركان الإيمان الستة، وأنواع التوحيد الثلاثة، ونواقض الإسلام، وينشأ على إفراد الله بالعبادة وترك الشرك بكل صوره. فالعقيدة أساسٌ لا يُبنى عليه غيره، كما قال تعالى: «فاعلم أنه لا إله إلا الله».\n\nومن هديه في ذلك: تعلّم التوحيد قبل الأحكام، والبدء بالأهمّ فالأهمّ، وفهم النصوص كما فهمها السلف، وترك الجدال في القدر والصفات ابتداءً، والحرص على العمل بما تعلّم؛ فإنّ العلم بلا عمل حجّة على صاحبه.\n\nوأنصح في هذه المرحلة: قراءة متونٍ مختصرة في العقيدة كـ«الأصول الثلاثة» و«كتاب التوحيد»، وحضور دروس أهل العلم، ومصاحبة من يعين على الطاعة؛ فإنّ الاعتقاد الصحيح أساس الاستقامة وثبات القلب.',
    en: 'The first thing a student of knowledge begins with is correcting creed: learning the six pillars of faith, the three types of monotheism, the nullifiers of Islam, and growing up singling out God in worship and abandoning polytheism in all its forms. Creed is a foundation on which nothing else is built, as He said: "know that there is no deity but God."\n\nHis guidance here: learning monotheism before rulings, beginning with the most important, understanding texts as the early generations understood them, avoiding dispute over decree and attributes at the outset, and acting upon what one learns; for knowledge without action is an argument against its possessor.\n\nAdvice at this stage: reading concise creed texts such as "The Three Principles" and "The Book of Monotheism," attending the lessons of scholars, and keeping company with those who help one obey; for sound belief is the foundation of uprightness and the heart\u0027s firmness.',
  },
  'lesson-learnsteps-2': {
    ar: 'بعد تصحيح الاعتقاد يأتي تعلّم أحكام الطهارة والصلاة؛ فهما مفتاح العبادة وشرط صحّتها. فيتعلّم الطالب الوضوء وموجباته، والغسل، والتيمّم عند فقد الماء أو العجز، وأحكام النجاسة والمياه، ثم أحكام الصلاة: شروطها، وأركانها، وواجباتها، وسننها، ومبطلاتها، وصلاة الجماعة والجمعة.\n\nومن هديه ﷺ: «صلّوا كما رأيتموني أصلّي»، فالتعلّم في هذا الباب يكون بالفقه وبالمشاهدة والتدريب؛ ويُستحسن أن يُصلّي الطالب خلف إمامٍ ويُصحّح له من هو أعلم منه. ويُضاف إلى ذلك صلاة الوتر والسنن الرواتب، وأحكام السهو والسجود له.\n\nوغاية هذا الباب: أداء العبادة على وجهها؛ \"حتى تعبد الله على بصيرة\"، فالعبادة بلا علمٍ قريبةٌ من الخطأ، والعلم بلا عبادةٍ وبالٌ على صاحبه. ومن يستقم على الطهارة والصلاة تُيسَّر له ما بعدها من العبادات والمعاملات.',
    en: 'After correcting belief comes learning the rulings of purity and prayer; they are the key to worship and the condition of its validity. The student learns ablution and what necessitates it, bathing, dry ablution when water is unavailable or one is unable, and the rulings of impurity and water, then the rulings of prayer: its conditions, pillars, obligations, recommended acts, invalidators, and the congregational and Friday prayers.\n\nHis guidance: "pray as you have seen me pray," so learning here is through jurisprudence and through observation and practice; it is preferable that the student pray behind an imam and be corrected by one more knowledgeable. Added to this are the night prayer, the regular supererogatory prayers, and the rulings of forgetfulness and its prostration.\n\nThe aim of this chapter is performing worship properly, "so that you worship God with insight"; worship without knowledge is close to error, and knowledge without worship is a burden on its possessor. Whoever is upright in purity and prayer will find what follows of worship and dealings made easy.',
  },
  'lesson-learnsteps-3': {
    ar: 'الخطوة الثالثة: القراءة اليومية للقرآن بتدبّر؛ فيجعل الطالب لنفسه وردًا ثابتًا لا يتركه، مع فهم المعاني ومراجعة تفسيرٍ ميسّر؛ فالمقصود من التلاوة العمل والاعتبار، قال تعالى: «كتابٌ أنزلناه إليك مباركٌ ليتدبّروا آياته وليتذكّر أولو الألباب».\n\nوأنفع ما يُعين على الورد: تخصيص وقتٍ محدّد في اليوم، والبدء بقدرٍ يسير كصفحةٍ أو نصف جزء، ثم التوسّع بحسب القدرة، وكثرة الاستماع إلى القرّاء المتقنين، وكتابة المعاني والفوائد، ومراجعة المحفوظ مع التلاوة.\n\nويُنبّه على أخطاء: أن يقرأ الطالب كثيرًا بلا فهم، أو يتوقّف عن الورد لأول انقطاع، أو ينشغل بالجدال عن التلاوة. وأثر الورد اليومي: صفاء القلب، وطرد الهمّ، وحفظ اللسان، والبركة في الوقت، ودوام الصلة بالله؛ وهو من أعظم ما يعين على الثبات في زمن الفتن.',
    en: 'The third step: daily recitation of the Quran with reflection. The student sets a fixed portion he never abandons, understanding the meanings and consulting an accessible exegesis; the aim of recitation is action and lesson, as He said: "a blessed Book which We have revealed to you so they may reflect on its verses and so the people of understanding may remember."\n\nMost helpful for the portion: setting a specific time of day, beginning with a small amount such as a page or half a part, then expanding according to capacity, listening often to skilled reciters, writing down meanings and benefits, and reviewing what is memorised alongside recitation.\n\nErrors to note: reading much without understanding, stopping the portion at the first interruption, or being distracted by dispute from recitation. The effects of a daily portion: clarity of heart, dispelling worry, guarding the tongue, blessing in time, and a continuous connection with God; it is among the greatest aids to steadfastness in times of trial.',
  },
  'lesson-learnsteps-4': {
    ar: 'الخطوة الرابعة: تعلّم السيرة النبوية؛ فيقرأ الطالب سيرة النبي ﷺ قراءةً تحليليةً: مولده، ونشأته، وبدء الوحي، ومراحل الدعوة في مكة، والهجرة، وبناء الدولة في المدينة، والغزوات، والمعاهدات، ووفاته؛ مع النظر في أخلاقه ﷺ في البيوت والحروب والخصومات.\n\nوفائدة السيرة: معرفة القدوة العملية كما قال تعالى: «لقد كان لكم في رسول الله أسوةٌ حسنة»، وإدراك كيف تُبنى الدعوة وتمرّ بمراحل، وفهم حكمة التشريع في سياقه، ومعرفة أسماء الصحابة وأخبارهم فيَتحبّب إليهم ويقتدي بهم.\n\nويُستحسن في هذه المرحلة: قراءة السيرة المنتقاة مع شروحها، وحفظ تواريخ الأحداث الكبرى، والاستفادة من دُرَر الفوائد لا مجرّد الأخبار، ثم تطبيق ما تعلّمه من أخلاق النبي ﷺ في بيته وعمله؛ فالسيرة منهج حياة لا حكايات تُروى.',
    en: 'The fourth step: learning the Prophet\u0027s biography. The student reads it analytically: his birth, upbringing, the beginning of revelation, the stages of dawah in Makkah, the migration, the building of the state in Madinah, the battles, the treaties, and his death; while considering his character in homes, wars, and disputes.\n\nThe benefit of the biography: knowing the practical example, as He said: "you have in the Messenger of God a good example," understanding how dawah is built and passes through stages, grasping the wisdom of legislation in context, and learning the names and accounts of the companions so as to love and follow them.\n\nRecommended at this stage: reading a selected biography with its commentaries, memorising the dates of major events, drawing benefits rather than mere reports, then applying what one learns of the Prophet\u0027s character in one\u0027s home and work; the biography is a method of life, not tales recited.',
  },
  'lesson-learnsteps-5': {
    ar: 'الخطوة الخامسة: تزكية النفس بتحسين الأخلاق؛ فيتعلّم الطالب الأخلاق المحمودة (الصدق، والأمانة، والحياء، والحلم، والرحمة، والوفاء) ويتجنّب المذمومة (الكبر، والحسد، والغشّ، والغضب غير المحسوب، والتسويف)، ويعالج قلبه بالمجاهدة والمحاسبة.\n\nوأساس التزكية: العلم بالداء والدواء، ومحاسبة النفس في كل يوم، والإكثار من الذكر والدعاء، ومصاحبة من يُعين على الطاعة، وترك مواطن الفتنة، والتدرّج في ترك المعاصي؛ فإنّ النفس إذا أُهملت أفسدت، وإذا حوسبت استقامت.\n\nوقاعدة الباب: «العلم بلا عمل كالشجرة بلا ثمر»؛ فهو ثمرة العلم ونتيجته، وهو أثقل ما يوضع في ميزان المؤمن يوم القيامة. ومن يجمع بين العلم والأخلاق ينتفع به الناس ويثبت أمام الفتن؛ فالدين حسن الخلق كما قال ﷺ: «أكمل المؤمنين إيمانًا أحسنهم خلقًا».',
    en: 'The fifth step: purifying the self by refining character. The student learns praiseworthy traits (truthfulness, trustworthiness, modesty, forbearance, mercy, loyalty) and avoids blameworthy ones (arrogance, envy, deceit, uncalculated anger, procrastination), treating his heart through striving and self-accounting.\n\nThe basis of purification: knowing the disease and the cure, daily self-accounting, abundant remembrance and supplication, keeping company with those who help one obey, avoiding places of temptation, and gradualness in abandoning sins; for the self, when neglected, corrupts, and when held to account, becomes upright.\n\nThe rule of this chapter: "knowledge without action is like a tree without fruit"; it is the fruit and outcome of knowledge, and the heaviest thing placed in a believer\u0027s scale on the Day of Judgement. Whoever combines knowledge with character benefits people and stands firm before trials; religion is good character, as the Prophet said: "the most complete of the believers in faith are the best of them in character."',
  },
  'lesson-lessons-1': {
    ar: 'سلسلة أركان الإيمان الستة: الإيمان بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، والقدر خيره وشره. وقد جمعها القرآن في قوله: «ولكنّ البرّ من آمن بالله واليوم الآخر والملائكة والكتاب والنبيين»، وفصّلها النبي ﷺ في حديث جبريل حين سُئل عن الإيمان.\n\nوأصول كل ركن: فالإيمان بالله يشمل توحيد الربوبية والألوهية والأسماء والصفات؛ والإيمان بالملائكة تصديقٌ بوجودهم ووظائفهم والكرماء الكتبة منهم؛ والإيمان بالكتب تصديقٌ بأنّها وحي الله، وأنّ القرآن آخرها ومهيمنٌ عليها؛ والإيمان بالرسل إجمالًا وتفصيلًا لما ذُكر؛ والإيمان باليوم الآخر يشمل البعث والحساب والصراط والميزان والجنة والنار؛ والإيمان بالقدر مراتبه الأربع وكسب العبد.\n\nودرس هذا الركن: أنّ الإيمان مبنيّ على أصولٍ يعتقدها القلب ويُصدّقها العمل لا مجرّد تصوّرات ذهنية. من ثمرات الإيمان بهذه الأركان: الاستقامة على الطاعة، ومحبة الأولياء والصالحين، والرغبة في الآخرة، والطمأنينة عند المصائب، والتسلّي بموعود الكتب الإلهية.',
    en: 'The series on the six pillars of faith: belief in God, His angels, His books, His messengers, the Last Day, and decree both good and bad. The Quran gathers them: "but righteousness is he who believes in God, the Last Day, the angels, the Book, and the prophets," and the Prophet detailed them in the hadith of Gabriel when asked about faith.\n\nThe foundations of each: belief in God includes the oneness of Lordship, worship, and names and attributes; belief in angels is affirming their existence, roles, and the noble scribes among them; belief in the books is affirming they are God\u0027s revelation and that the Quran is the last and dominant over them; belief in the messengers is in general and in detail for those mentioned; belief in the Last Day includes resurrection, reckoning, the bridge, the scale, Paradise and Hell; and belief in decree includes its four levels and the servant\u0027s acquisition.\n\nThe lesson of this pillar: faith rests on foundations the heart believes and action confirms, not mere mental notions. Its fruits: uprightness in obedience, love for the righteous, desire for the Hereafter, tranquillity in calamity, and consolation in what the divine books promise.',
  },
  'lesson-lessons-2': {
    ar: 'دورة عملية في فقه الطهارة والصلاة، مبنيّة على التدرّج من النظري إلى التطبيق. تبدأ بدروس الطهارة: أنواع المياه، والأحكام المتعلقة بها، والنجاسات وكيفية إزالتها، ثم الوضوء: صفته وموجباته ونواقضه، والمسح على الخفّين والجبيرة، والتيمّم وأحكامه.\n\nثم دروس الصلاة: شروطها، والأوقات، والأذان والإقامة، وصفة الصلاة وأركانها وواجباتها وسننها، والطمأنينة فيها، ثم مبطلات الصلاة، وسجود السهو، وصلاة الجماعة والجمعة، وصلاة المسافر والمريض، والسنن الرواتب والوتر.\n\nويُشترط للدورة: التطبيق العملي أمام المدرّب، ومراجعة الفروق، وحلّ التدريبات؛ فالمقصود إتقان الأداء لا حفظ المعلومات. ويُستفاد من قوله ﷺ: «صلّوا كما رأيتموني أصلّي» أنّ العبادة يُجمع فيها بين العلم والمشاهدة والتصحيح، فمن أتقن الطهارة والصلاة فقد أدرك أهمّ ما أُمر به عمليًّا.',
    en: 'A practical course in the jurisprudence of purity and prayer, built on progressing from theory to application. It begins with lessons on purity: types of water and related rulings, impurities and how to remove them; then ablution: its description, what necessitates it, what invalidates it, wiping over socks and splints, and dry ablution and its rulings.\n\nThen lessons on prayer: its conditions, the times, the call and the second call, the description of prayer with its pillars, obligations, and recommended acts, tranquillity in it, then what invalidates prayer, the prostration of forgetfulness, congregational and Friday prayer, the prayer of the traveller and the sick, the regular supererogatory prayers, and the night prayer.\n\nThe course requires: practical performance before the trainer, reviewing differences, and solving exercises; the aim is mastery of performance, not memorising information. From the Prophet\u0027s words "pray as you have seen me pray" we learn that worship combines knowledge, observation, and correction; whoever masters purity and prayer has attained the most important practical obligations.',
  },
  'page-places-1': {
    ar: 'مسجد النور أحد المساجد التي تُعقد فيها الدروس وحلقات التحفيظ، ويخدم أهل الحي بتعليم القرآن وحفظه، وبإقامة الصلوات الخمس والجمعة، وبدروس التفسير والفقه والتزكية على مدار الأسبوع.\n\nومن برامجه: حلقة تحفيظ القرآن للناشئة والكبار، ودروس أحكام التلاوة والتجويد، وحلقة اللغة العربية لخدمة فهم القرآن، ودروس التفسير، والدورات الموسمية في رمضان.\n\nويُسهم المسجد في بناء الأسرة المسلمة بإشراف عددٍ من المعلمين، وتشجيع الناشئة على الحفظ، وتكريمهم على مراتبهم؛ ومن يسّر الله له فعل الخير فيه فقد أدرك بركة القرآن: «ومن بركة العلم أن يُعظَّم في المساجد».',
    en: 'Al-Nur Mosque is among the mosques where lessons and memorisation circles are held; it serves the neighbourhood by teaching and memorising the Quran, establishing the five daily prayers and Friday prayer, and holding weekly lessons on exegesis, jurisprudence, and purification.\n\nIts programmes include: a Quran memorisation circle for youth and adults, lessons on recitation and tajwid, an Arabic circle supporting Quranic understanding, exegesis lessons, and seasonal courses in Ramadan.\n\nIt contributes to building the Muslim family under the supervision of teachers, encouraging the youth to memorise and honouring them for their ranks; whoever God enables to do good in it has attained the blessing of the Quran: the blessing of knowledge is that it be honoured in mosques.',
  },
  'page-places-2': {
    ar: 'المسجد الكبير من أقدم مساجد المدينة، ويُعدّ مركزًا للدعوة والتعليم في المنطقة؛ يستقبل المصلين في الصلوات الخمس والجمعة والتراويح، ويحتضن حلقات التحفيظ ودروس العلم، ويسهم في المناسبات الدينية كالإفطار الجماعي في رمضان وموائد الرحمة.\n\nومن مسؤولياته التعليمية: تنظيم دورات في علوم القرآن والسنة والفقه، ورعاية الناشئة بحلقات التحفيظ، وإقامة الدروس الأسبوعية للرجال والنساء على حِدة، وتنسيق الدعوة مع الجمعيات الخيرية لإغاثة الأسر وخدمة القرية.\n\nويُعرف المسجد بجودة التلاوة وروح الأخوّة بين المصلّين؛ ورسالته: أن يكون بيتًا لله يُعمَّر بالطاعة، ومنارةً للعلم الشرعي، ومنطلقًا لخدمة المجتمع؛ فالمساجد إنما عُمرت لذكر الله كما في قوله: «في بيوتٍ أذن الله أن تُرفع ويُذكر فيها اسمه».',
    en: 'The Grand Mosque is among the city\u0027s oldest mosques and is a centre of dawah and education in the area. It receives worshippers for the five prayers, Friday prayer, and the night prayers of Ramadan, hosts memorisation circles and lessons of knowledge, and contributes on religious occasions such as communal iftar in Ramadan and charity tables.\n\nIts educational responsibilities: organising courses in Quranic sciences, Sunnah, and jurisprudence; caring for the young through memorisation circles; holding weekly lessons for men and women separately; and coordinating dawah with charitable associations for family relief and village service.\n\nIt is known for the quality of recitation and the spirit of brotherhood among worshippers. Its mission: to be a house of God maintained by obedience, a beacon of revealed knowledge, and a starting point for serving the community; mosques are built for the remembrance of God, as in "in houses which God has ordered to be raised, in which His name is remembered."',
  },
  'page-projects-1': {
    ar: 'مشروع «طباعة وتوزيع جزء عمّ» يهدف إلى تعليم الناشئة القرآن الكريم وترغيبهم في الحفظ؛ فيُطبع المصحف المجزّأ بتنسيق واضحٍ سهل القراءة، ويُوزّع مجانًا على طلاب الكتاتيب والمساجد في القرى، مع إخراج نسخ مناسبة للمبتدئين.\n\nويشمل المشروع: توزيع 1000 نسخة على الطلاب، وتنظيم مسابقات في الحفظ بين الحلقات، وإقامة دروسٍ تعريفية بأحكام التلاوة، ومتابعة الطلاب مع المعلّمين لتثبيت المحفوظ. ويُعتمد فيه على الدعم الخيري والتبرّعات، فلا يُلزم الطالب بأي مبلغ.\n\nوأثره: كثرة الحافظين في القرى، وتصحيح التلاوة، وتشجيع الأسر على حفظ القرآن وتدبّره؛ قال ﷺ: «خيركم من تعلّم القرآن وعلّمه»، وهو مشروع صدقة جارية يشارك في أجره كل من أسهم فيه.',
    en: 'The "Printing and Distributing Juz Amma" project aims to teach children the Quran and encourage them to memorise it. A sectioned copy is printed with clear, easy-to-read formatting and distributed free of charge to students of Quranic schools and mosques in villages, with editions suited to beginners.\n\nThe project includes: distributing one thousand copies to students, organising memorisation competitions among circles, holding introductory lessons on recitation rules, and following up with students and teachers to consolidate what is memorised. It relies on charitable support and donations, imposing no cost on students.\n\nIts effect: more memorisers in villages, corrected recitation, and encouraging families to memorise and reflect on the Quran. The Prophet said: "the best of you are those who learn the Quran and teach it," and it is an ongoing charity in whose reward all who contribute share.',
  },
  'page-projects-2': {
    ar: 'مشروع «تجهيز قاعة الدروس الدعوية» يهدف إلى إيجاد مكانٍ لائقٍ للدروس وحلقات العلم، فتتسع القاعة لنحو 200 طالب علم، وتُجهَّز بالفرش والكراسي والوسائل التعليمية ووسائل العرض، وتُزوَّد بمكتبة مصغّرة تحوي الكتب والمراجع التي يحتاجها الطالب.\n\nويُشرف على القاعة: إقامة دروس أسبوعية في التفسير والفقه والعقيدة والسيرة، ودورات مكثّفة في الإجازات، ومجالس لحفظ المتون، وحلقات تحفيظ القرآن للرجال والنساء؛ مع تنسيق مع المعلّمين لجدولة الدروس.\n\nوأثره: بناء طالب علمٍ منتظم، وتوسيع قاعدة التعلّم، وإحياء مجالس العلم في المنطقة، وخدمة الدعوة إلى الله على بصيرة. ومن مقاصد المشروع: أن يكون المكان وقفًا لله، والصدقة الجارية فيه تُثمر علمًا يُنتفع به، كما في الحديث: «إذا مات ابن آدم انقطع عمله إلا من ثلاث... أو علمٍ يُنتفع به».',
    en: 'The "Equipping the Dawah Lessons Hall" project aims to provide a suitable place for lessons and study circles. The hall accommodates about two hundred students and is furnished with seating, teaching aids, and presentation equipment, and supplied with a small library of the books and references a student needs.\n\nThe hall hosts: weekly lessons in exegesis, jurisprudence, creed, and biography; intensive courses during holidays; sessions for memorising foundational texts; and Quran memorisation circles for men and women, with lessons scheduled in coordination with teachers.\n\nIts effect: forming consistent students, widening the base of learning, reviving study gatherings in the area, and serving the call to God with insight. The project aims for the place to be an endowment for God, and ongoing charity in it yields knowledge that benefits others, as in the hadith: "when a person dies his deeds cease except for three... or knowledge that benefits."',
  },
  'video-videos-1': {
    ar: 'كلمة موجزة عن حقيقة العبودية لله، وعنوانها سؤال: لماذا خُلقنا؟ والجواب في قوله تعالى: «وما خلقت الجنّ والإنس إلا ليعبدون»، فالعبادة هي الغاية التي خُلق لها الإنسان، وليست تكليفًا يعطّل الحياة بل هي نظامها.\n\nوتُبيّن الكلمة أنّ العبودية شاملة: عبودية الطاعة في الأوامر، وتجنّب النواهي، والاستعانة والتوكّل، والدعاء والذلّ لله بالقلب؛ وأنّ أعظم ما يعين العبد على الثبات: إخلاص القصد، والدعاء، ومصاحبة الصالحين، ومراقبة القلب، والبعد عن الشرك ودوافعه.\n\nونصيحة الكلمة: أن يراجع كلّ إنسان بوصلة حياته: فمن عرف غاية خلقه لم يضيّع عمره في غيرها، ولم يتحرّك إلا حيث ترجّح لله أجرًا؛ فالحرّية الحقيقية في العبودية لله وحده، وما سواها عبودية للمخلوق أو للشهوة.',
    en: 'A brief talk on the reality of servitude to God, titled with the question: why were we created? The answer is in His words: "I did not create jinn and mankind except to worship Me." Worship is the purpose for which man was created; it is not an obligation that halts life but its organising principle.\n\nThe talk shows that servitude is comprehensive: obedience to commands, avoiding prohibitions, seeking help and reliance, supplication, and humility before God in the heart. It notes that the greatest aids to steadfastness are sincerity of purpose, supplication, righteous company, watching the heart, and keeping away from polytheism and its causes.\n\nThe talk advises every person to review the compass of his life: whoever knows the purpose of his creation does not waste his life elsewhere and moves only where God\u0027s reward is more likely. True freedom is in servitude to God alone; anything else is servitude to a creature or to desire.',
  },
  'page-tools-مواقيت-الصلاة-كيف-تُحسب-32': {
    ar: 'مواقيت الصلاة تُبنى على حركة الشمس الظاهرية بالنسبة لموقع المكان؛ فيُحدَّد الفجر بظهور الفجر الصادق (البياض المعترض في الأفق شرقًا)، والظهر بزوال الشمس عن وسط السماء، والعصر بميل ظلّ الشيء مثله، والمغرب بغروب قرص الشمس، والعشاء بمغيب الشفق الأحمر.\n\nومدار الحساب على ثلاثة عناصر: خط عرض المكان، وخط الطول، والتاريخ؛ فيُحتسب موقع الشمس وفروق مطالعها، ويُزاد احتياطٌ للفجر والعشاء قدر دقيقتين إلى ثلاث عند كثير من التقاويم لضمان دخول الوقت. وتُعتمد الحسابات الفلكية المعتمدة في كثير من الدول، ويُتحقّق من صحّتها بالفجر والعشاء بالعين.\n\nويُستحبّ للمصلّي: أن يكون عنده تقويم موثوق لبلده، وأن يعرف على الأقل الفروق بين الصلوات كما هي في مدينته، وألّا يبني يقينه على إحساسه فقط؛ فالصلاة تُؤدّى في وقتها: «إنّ الصلاة كانت على المؤمنين كتابًا موقوتًا».',
    en: 'Prayer times are based on the apparent movement of the sun relative to a given location. The dawn prayer begins with the true dawn, the white light spreading across the eastern horizon; noon with the sun\u0027s decline from the middle of the sky; afternoon when an object\u0027s shadow equals its length; sunset with the setting of the sun\u0027s disc; and the evening prayer with the disappearance of the red twilight.\n\nThe calculation rests on three elements: the latitude, the longitude, and the date; the sun\u0027s position and the differences in its rising are computed, and a precaution of two to three minutes is added for dawn and evening in many calendars to ensure the time has entered. Astronomical calculations adopted in many countries are relied upon, and they are checked against the eye at dawn and evening.\n\nIt is recommended for the worshipper: to have a reliable calendar for his country, to know at least the differences between prayers as they are in his city, and not to base certainty on feeling alone; prayer is performed at its time: "prayer has been enjoined on the believers at fixed times."',
  },
  'page-tools-اتجاه-القبلة-كيف-تعرفه-33': {
    ar: 'القبلة هي الكعبة المشرّفة في مكة المكرمة، واستقبالها شرطٌ في صحة الصلاة مع القدرة؛ قال تعالى: «فولّ وجهك شطر المسجد الحرام». ومعرفة الاتجاه تعتمد على حساب المسافة الجغرافية بين موقعك ومكة، وليس على الجهات الأصلية فقط؛ فمن كان شمال مكة يستقبل الجنوب، ومن كان جنوبها يستقبل الشمال بانزياحٍ بحسب خط الطول.\n\nوطريقة التحديد: استخدام البوصلة مع قيمة الانحراف المغناطيسي لموقعك، أو حسابات الخرائط والمواقع المعتمدة، أو بمراقبة الشمس في وقت الظهيرة (فإنّ ظلّ القائم في نصف الكرة الشمالي في الظهيرة يشير شمالًا). ويُستحسن التحقّق مرتين على الأقل لمن كان مسافرًا أو لا يحسن التقدير، ومن عجز أدّى بحسب اجتهاده وصلاته صحيحة.',
    en: 'The qibla is the Sacred House in Makkah, and facing it is a condition of valid prayer when one is able; He said: "so turn your face toward the Sacred Mosque." Determining its direction depends on computing the geographic bearing between your location and Makkah, not on the cardinal points alone; one north of Makkah faces south, and one south of it faces north with a deviation according to longitude.\n\nThe method: using a compass with the magnetic declination for your location, or the calculations of reliable maps and applications, or observing the sun at noon, since the shadow of an upright object in the northern hemisphere at noon points north. It is recommended to verify at least twice for a traveller or one who cannot estimate well; whoever is unable performs according to his best judgement and his prayer is valid.',
  },
  'hadith-hadith-حديث-لا-يؤمن-أحدكم-حتى-يحب-لأخيه-ما-يحب-لنفسه-11': {
    ar: 'عن أنس بن مالك رضي الله عنه عن النبي ﷺ قال: «لا يؤمن أحدكم حتى يحبّ لأخيه ما يحبّ لنفسه». والحديث رواه البخاري ومسلم، وهو من جوامع كلمه ﷺ التي تُنظّم علاقة المسلم بأخيه.\n\nومعنى الحديث: أنّ كمال الإيمان لا يحصل لمن استأثر بالخير وحده؛ بل المؤمن حقيقةً من يحبّ لإخوانه من الخير ما يحبّه لنفسه، ويكره لهم ما يكرهه لنفسه. وهو مبنيّ على محبّة الخير للناس، وأصلها سلامة القلب من الحسد والغلّ، كما قال ﷺ: «دبّ إليكم داء الأمم قبلكم: الحسد والبغضاء».\n\nوثمراته في الواقع: شيوع التعاون والتكافل، وطيب النفس بما يُصيب الآخرين، وقِلّة الشحّ والحسد، وأداء النصيحة وإعانة المحتاج. ومن علامة صدق المحبّة: أن يعمل لها لا أن يدّعيها؛ فيفرح لإحسان غيره، ويَدفع الأذى عن أخيه، ويحبّ له الهداية كما يحبّها لنفسه.',
    en: 'Anas ibn Malik reported that the Prophet said: "None of you truly believes until he loves for his brother what he loves for himself." The hadith is narrated by al-Bukhari and Muslim and is among his comprehensive words that organise a Muslim\u0027s relationship with his brother.\n\nIts meaning: faith is not complete for one who keeps good to himself alone; the true believer loves for his brothers the good he loves for himself and dislikes for them what he dislikes for himself. It rests on loving good for people, whose root is a heart free of envy and rancour, as he said: "the disease of the nations before you has crept to you: envy and hatred."\n\nIts fruits in practice: spreading cooperation and mutual support, contentment with what befalls others, little miserliness and envy, giving sincere counsel, and aiding the needy. A sign of true love is acting upon it rather than claiming it: rejoicing in another\u0027s goodness, removing harm from one\u0027s brother, and loving guidance for him as for oneself.',
  },
  'page-non-muslim-ما-هو-الإسلام؟-دليل-موجز-لغير-المسلمين-29': {
    ar: 'الإسلام دين التوحيد، يقوم على أنّ الله واحدٌ لا شريك له، خالقٌ لهذا الكون ومدبّرٌ له، وأنّه سبحانه وحده المستحقّ للعبادة. وقد جاء به الأنبياء جميعًا: نوح وإبراهيم وموسى وعيسى ومحمد ﷺ؛ فالإسلام هو دين الأنبياء وختامه برسالة محمد ﷺ.\n\nوأركانه خمسة: شهادة أن لا إله إلا الله وأنّ محمدًا رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحجّ البيت لمن استطاع. ويتضمّن الإيمان أركانًا ستة: الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر والقدر.\n\nوهو منهجٌ شامل للعبادة والأخلاق والمعاملات والأسرة والمجتمع؛ يدعو إلى العدل والرحمة والصدق والأمانة، ويحرّم الظلم والربا والغشّ، ويحفظ للنفس والدين والعقل والعرض والمال. ومن أراد أن يعرفه فليقرأ القرآن، وليبادر بالشهادتين؛ فإنّه لا يحتاج أكثر من صدق النية.',
    en: 'Islam is the religion of monotheism, resting on the fact that God is one with no partner, the creator and disposer of this universe, and that He alone deserves worship. All the prophets brought it: Noah, Abraham, Moses, Jesus, and Muhammad; Islam is the religion of the prophets, sealed with the message of Muhammad.\n\nIts pillars are five: the testimony that there is no deity but God and that Muhammad is His messenger; establishing prayer; giving zakat; fasting Ramadan; and pilgrimage to the House for those able. Faith includes six pillars: belief in God, His angels, His books, His messengers, the Last Day, and decree.\n\nIt is a comprehensive way for worship, ethics, dealings, family, and society; it calls to justice, mercy, truthfulness, and trustworthiness, forbids injustice, usury, and deceit, and protects life, religion, intellect, honour, and wealth. Whoever wishes to know it should read the Quran and hasten to the testimony of faith; nothing more than sincere intention is required.',
  },
  'page-non-muslim-مقارنة-الأديان-الإسلام-والمسيحية-واليهودية-30': {
    ar: 'الدعوة إلى توحيد الله هي الكلمة المشتركة بين الأديان السماوية؛ قال تعالى: «قل يا أهل الكتاب تعالوا إلى كلمةٍ سواءٍ بيننا وبينكم ألّا نعبد إلا الله ولا نشرك به شيئًا». وقد أرسل الله الأنبياء جميعًا بهذا الأصل، فالتوحيد أساس مشترك بين اليهودية والمسيحية والإسلام.\n\nوأوجه الاتفاق: الإيمان بالله الخالق، وبالوحي والرسل، وباليوم الآخر، وبالأخلاق والقيم. وأوجه الافتراق: مسألة التثليث في المسيحية، وادّعاء بنوّة الله لبعض الخلق، وتحريف النصوص عند أهل الكتاب، ثم نسخ الشرائع السابقة بشريعة محمد ﷺ وختم الرسالات به.\n\nوموقف الإسلام من أهل الكتاب: الإقرار بأنّ أصلهم على كتابٍ منزل، والإحسان إليهم، والمناظرة بالتي هي أحسن، والعدل معهم في الحقوق؛ قال تعالى: «لا ينهاكم الله عن الذين لم يقاتلوكم في الدين ولم يخرجوكم من دياركم أن تبرّوهم وتقسطوا إليهم». فالمقارنة تُبنى على العلم والإنصاف لا على الطعن.',
    en: 'The call to the oneness of God is the common word among the revealed religions; He said: "Say: O People of the Book, come to a word common between us and you, that we worship none but God and associate nothing with Him." God sent all the prophets with this principle, so monotheism is a shared foundation of Judaism, Christianity, and Islam.\n\nPoints of agreement: belief in God the Creator, in revelation and messengers, in the Last Day, and in ethics and values. Points of difference: the doctrine of the Trinity in Christianity, claims of divine sonship for some creatures, distortion of texts among the People of the Book, and then the abrogation of earlier laws by the law of Muhammad and the sealing of messages with him.\n\nIslam\u0027s stance toward the People of the Book: acknowledging that their origin rests on a revealed book, treating them with kindness, debating them in the best manner, and being just with them in rights; He said: "God does not forbid you, regarding those who did not fight you over religion nor drive you from your homes, from being kind and just to them." Comparison is built on knowledge and fairness, not on disparagement.',
  },
  'page-non-muslim-كيف-تدخل-الإسلام؟-خطوات-مبسطة-31': {
    ar: 'الدخول في الإسلام يكون بالنطق بالشهادتين: «أشهد أن لا إله إلا الله، وأشهد أنّ محمدًا رسول الله»، مع تصديق القلب بمعناهما، والإيمان بجميع ما جاء به النبي محمد ﷺ. ومن نطق بهما صادقًا فقد دخل في الإسلام، وغُفر له ما كان قبل ذلك من الشرك؛ قال ﷺ: «الإسلام يهدم ما كان قبله».\n\nوخطوات عملية بعد الشهادة: الاغتسال، وتعلّم الطهارة والصلاة، والصلاة في أوقاتها، وتعلّم ما يحتاج إليه من أحكام الحلال والحرام تدريجيًّا، وقراءة القرآن بالتدبّر، ومصاحبة أهل الخير والدخول في حلقات العلم في المسجد.\n\nويُنبّه على ألّا يُستعجل المعلّم أو الداخل إلى ما يشقّ؛ فالتكليف مبنيّ على التدرّج واليسر: «يريد الله بكم اليسر ولا يريد بكم العسر». والمسلم الجديد يُستقبَل بالتيسير والتثبيت لا بالتعنيف؛ فإنّ أثره في حياة الناس أعظم وأبقى.',
    en: 'Entering Islam is done by uttering the two testimonies: "I bear witness that there is no deity but God, and I bear witness that Muhammad is the messenger of God," with the heart affirming their meaning and believing in all that the Prophet Muhammad brought. Whoever utters them truthfully has entered Islam and is forgiven the polytheism that preceded; he said: "Islam demolishes what came before it."\n\nPractical steps after the testimony: bathing, learning purity and prayer, praying at their times, gradually learning the rulings of the lawful and unlawful one needs, reciting the Quran with reflection, keeping good company, and joining study circles in the mosque.\n\nIt is important that the teacher or the new entrant not be rushed into what is difficult; obligation rests on gradualism and ease: "God intends ease for you and does not intend hardship for you." The new Muslim should be received with facilitation and consolidation, not harshness; for its effect on people\u0027s lives is greater and more lasting.',
  },
};

async function main() {
  const res = await fetch(
    `${URL}/rest/v1/content_translations?select=id,lang,slug,body&limit=1000`,
    { headers: H }
  );
  if (!res.ok) throw new Error(`${res.status} ${await res.text()}`);
  const rows = await res.json();

  const targets = rows.filter((r) => BODIES[r.slug]);
  const found = new Set(targets.map((r) => `${r.slug}|${r.lang}`));

  console.log('=== تعمير المتون المقتضبة ===');
  console.log(`عناصر مستهدفة: ${Object.keys(BODIES).length}`);
  console.log(`صفوف ستُحدّث: ${targets.length}`);
  console.log('------------------------------------------------------------');

  for (const slug of Object.keys(BODIES)) {
    const hasAr = found.has(`${slug}|ar`);
    const hasEn = found.has(`${slug}|en`);
    if (!hasAr || !hasEn) {
      console.log(`✖ ${slug} — ar:${hasAr ? '✔' : '✖'} en:${hasEn ? '✔' : '✖'}`);
    }
  }

  if (!COMMIT) {
    console.log('\n(معاينة فقط) للتنفيذ: --commit');
    return;
  }

  let done = 0;
  for (const row of targets) {
    const body = BODIES[row.slug][row.lang];

    // نُدرِج الملخّص القديم في المقدّمة إن كان مفيدًا ولم يكن مكرّرًا
    const patch = { body, body_plain: body };
    const r2 = await fetch(`${URL}/rest/v1/content_translations?id=eq.${row.id}`, {
      method: 'PATCH',
      headers: { ...H, Prefer: 'return=minimal' },
      body: JSON.stringify(patch),
    });
    if (!r2.ok) throw new Error(`PATCH ${row.slug}: ${r2.status} ${await r2.text()}`);
    done += 1;
  }

  console.log(`✔ تم تعمير ${done} متنًا.`);
}

main().catch((err) => {
  console.error('✖ فشل:', err.message);
  process.exit(1);
});
